-- SAMPLE DATA: department heads and secretaries for every active department that lacks one, plus 3 staff in each
-- department that had nobody (and in ICT Infrastructure DEP-048 and Technical Services DEP-006): 288 people
-- (57 heads, 60 secretaries, 171 staff), each with a current job record and an EMPLOYEE login.
-- DEVELOPMENT DATABASES ONLY: every login shares one password and is not asked to change it (test logins).
-- A head/secretary is created only while that slot is empty; existing heads and secretaries are never replaced.
-- Missing departments are skipped. Reporting: heads -> General Manager (anil.mehta@nilepet.com, if present); secretaries and
-- staff -> their department head. Safe to run twice: a row that exists is skipped.
-- Needs: EMPLOYEE role, office location JUBA_HQ, branch JUBA_HO, work shift 5. Run as the HRMS user.
-- Written by tools/generate_dept_heads_secretaries.py. Undo: db/seed_dept_heads_secretaries_rollback.sql
--   Logins: username = the part of the work e-mail before @, password = Welcome123 (no change required).

-- ===== 1. Designations (Head of Department, Department Secretary, <Department> Officer; existing titles reused) =====
INSERT INTO HRMS.DESIGNATIONS (DESIG_ID, TITLE, CODE, DEPARTMENT_ID, IS_ACTIVE, TITLE_AR)
SELECT HRMS.SEQ_DESIGNATIONS.NEXTVAL, 'Head of Department', 'SDH-DEP-001-HEAD', d.DEPT_ID, 1, UNISTR('\0631\0626\064A\0633\0020\0627\0644\0642\0633\0645')
  FROM HRMS.DEPARTMENTS d WHERE d.CODE = 'DEP-001'
   AND NOT EXISTS (SELECT 1 FROM HRMS.DESIGNATIONS x WHERE x.CODE = 'SDH-DEP-001-HEAD'
                    OR (x.DEPARTMENT_ID = d.DEPT_ID AND UPPER(x.TITLE) = UPPER('Head of Department')));
