SELECT HRMS.AUTH_USER_SEQ.NEXTVAL, 'deng.lual', 'deng.lual@nilepet.com', 'Deng Lual', '$2a$10$AB7djb/EPnYxCRfvlYXBiO0npmoO6uVYLRXRxwTjbDOSTT0PyMQXe', 'EMPLOYEE', e.EMPLOYEE_ID, e.EMPLOYEE_CODE, TO_CHAR(e.DEPARTMENT_ID),
